import pandas as pd

DAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday"]

def weekday_means(close):
    r = close.sort_index().pct_change()
    means = r.groupby(r.index.day_name()).mean()
    return means.reindex(DAYS).round(6).to_dict()
